tool_input.command:
cat > src/features/teams/api/create-team.ts <<'EOF'
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { z } from 'zod';

import { api } from '@/lib/api-client';
import { MutationConfig } from '@/lib/react-query';
import { Team } from '@/types/api';

import { getTeamsQueryOptions } from './get-teams';

export const createTeamInputSchema = z.object({
  name: z.string().min(1, 'Required'),
  description: z.string().min(1, 'Required'),
});

export type CreateTeamInput = z.infer<typeof createTeamInputSchema>;

export const createTeam = ({ data }: { data: CreateTeamInput }): Promise<Team> => {
  return api.post('/teams', data);
};

type UseCreateTeamOptions = {
  mutationConfig?: MutationConfig<typeof createTeam>;
};

export const useCreateTeam = ({ mutationConfig }: UseCreateTeamOptions = {}) => {
  const queryClient = useQueryClient();
  const { addNotification } = useNotifications();

  const { onSuccess, ...restConfig } = mutationConfig || {};

  return useMutation({
    onSuccess: (...args) => {
      queryClient.invalidateQueries({
        queryKey: getTeamsQueryOptions().queryKey,
      });
      addNotification({
        type: 'success',
        title: 'Team Created',
      });
      onSuccess?.(...args);
    },
    ...restConfig,
    mutationFn: createTeam,
  });
};
EOF
grep -rn "addNotification" src/features --include=*.ts | head -5; grep -rn "useNotifications" src/features/*/api | head
